/** R01-REG-ENVIO: un solo registro (W77-NUMREG-CTL = 1) que guarda el avance y el estado del servicio. */
@Entity
@Table(name = "s151_control_domiciliacion")
public class ControlDomiciliacion {

    @Id
    private int id = 1;                         // ACTUAL KEY W77-NUMREG-CTL, siempre 1

    @Column(name = "aut_s500", nullable = false)
    private long autS500;                       // R01-REG-AUTS500 9(08): último registro de MOVS500 procesado

    @Column(name = "servicio_activo", nullable = false)
    private boolean servicioActivo;             // R01-REG-SER 9(01): 1 = envío a S702 activo (W88-SER-ACT)

    @Column(name = "ban_hr", nullable = false)
    private boolean reinicioPendAntHecho;       // R01-REG-BAN-HR 9(01) <-> WKS-RESET-HORA: 011290 ya corrió hoy

    @Version
    private long version;                       // sustituye a PROTECTION IS PROTECTED + REWRITE
}

/** WKS-SA2: identificación de la transacción en el diálogo COMS S151-S702. */
public record EncabezadoSa2(
        int identFmt, int reconoc,
        char version,                // "B" en los mensajes que arma P013
        int clase, int resultado, int modo,
        int sucursal,                // 9(04)
        String caja,                 // 9(03) con REDEFINES PRIV X(01) + CAJA 9(02): se conserva como texto
        long trnNum,                 // 9(08)
        LocalDate fecha,             // WKS-SA2-FECHA 9(06) AAMMDD
        LocalTime hora,              // WKS-SA2-HORA 9(06) HHMMSS
        int modalidad,
        String ieFeNope,             // X(10): INDEFECTIVO + FILLER + OPERADOR
        char verOpc) {

    /** Pivote explícito para el año de dos dígitos de WKS-SA2-FECHA. */
    private static final DateTimeFormatter AAMMDD =
            new DateTimeFormatterBuilder().appendValueReduced(ChronoField.YEAR, 2, 2, 2000)
                    .appendPattern("MMdd").toFormatter();

    static LocalDate fechaAammdd(String s) { return LocalDate.parse(s, AAMMDD); }
}

@Component
@RequiredArgsConstructor
public class DomiciliacionScheduler {

    private final InicioDomiciliacion inicio;     // 010000-INICIO: L001, S080, COMS, BIFIN
    private final CicloDomiciliacion ciclo;       // 020000-PROCESO
    private final RegistroProcesos b05;           // CALL B05PROCESOS

    @EventListener(ApplicationReadyEvent.class)
    void arranque() { inicio.ejecutar(); }

    @Scheduled(fixedDelayString = "${domiciliacion.ciclo:PT5S}")
    void vuelta() { ciclo.ejecutar(); }           // PERFORM 020000-PROCESO UNTIL W77-FIN = 1

    @PreDestroy
    void fin() {
        b05.baja(151, 13, 13);                    // FUNCION 22, SISTEMA 151, FCHPRO/NUMPRO 13
    }
}

@Service
@RequiredArgsConstructor
class CicloDomiciliacion {

    private final ControlDomiciliacionRepository control;
    private final DomiciliacionProperties props;     // hora-fin-servicio: "22:00", limites
    private final PendientesService pendientes;      // 021200 / 021300
    private final JobLauncher launcher;
    private final Job movimientosS500;               // 021600-MOVS500
    private final Clock clock;
    private boolean preguntaMatutinaHecha;           // WKS-BAN-HR, se limpia en 022100-CAMBIO-DIA

    @Transactional
    void ejecutar() {
        ControlDomiciliacion ctl = control.findById(1).orElseThrow();
        if (!preguntaMatutinaHecha) {                // WKS-BAN-HR = 0 (solo en memoria)
            activacionMatutina(ctl);                 // 021222-VALIDA-SERV
        }
        if (ctl.isServicioActivo()) {
            pendientes.enviaPendientes(props.limitePendientes());   // status 0 y 5, máx. W77-LIMITE-PENDIENTES
            pendientes.enviaReintentos(LocalTime.now(clock));
        }
        launcher.run(movimientosS500, new JobParametersBuilder()
                .addLong("desde", ctl.getAutS500() + 1)
                .addLong("limite", (long) props.limiteEnvios())       // W77-LIMITE-ENVIOS VALUE 300
                .toJobParameters());

        // 021700-VALIDA-HORARIO: después de las 22:00 se apaga el servicio hacia S702
        if (LocalTime.now(clock).isAfter(props.horaFinServicio()) && ctl.isServicioActivo()) {
            ctl.setServicioActivo(false);
            log.info("SE ACTIVO EL FIN DE SERVICIO DEL PROGRAMA X HORARIO");
        }
    }
}

@Component
@StepScope
@RequiredArgsConstructor
public class DomiciliacionProcessor implements ItemProcessor<MovimientoS500, MovimientoS500> {

    private final AltaDomiciliacion alta;           // 021640-ALTA-MOVS
    private final CancelacionDomiciliacion cancela; // 021621 / 021630

    @Override
    public MovimientoS500 process(MovimientoS500 m) {
        // El avance (W77-AUT-ENVIO500) se incrementa para todos los registros leídos.
        if (m.tipoProc() >= 40 && m.tipoProc() <= 43) {
            return m;                               // Teletón: no participa en domiciliación
        }
        switch (m.funcion()) {
            case 21, 22 -> cancela.porProceso(m);   // cancelación masiva por proceso
            case 2      -> cancela.porCadena(m);    // cancelación siguiendo AUT-AELIM-S151
            case 1      -> alta.registra(m);
            default     -> { }                      // cualquier otra función se ignora
        }
        return m;
    }
}

@Service
@RequiredArgsConstructor
class AltaDomiciliacion {

    private final CatalogoDomiciliacion catalogo;   // WKS-CVETRAN-DOMI OCCURS 10000, servicio 3
    private final B10DomiRepository b10;
    private final ControlDomiciliacionRepository control;
    private final S702Gateway s702;

    void registra(MovimientoS500 m) {
        boolean activo = control.servicioActivo();
        for (int occ = 1; occ <= 5; occ++) {
            int cveTran = m.cveTran(occ);
            if (cveTran == 0) break;                         // MOVE 6 TO WKS-NUM-OCCURS
            if (!catalogo.esDomiciliacion(cveTran)) continue;

            B10Domi reg = B10Domi.desde(m, occ);             // 021643-MUVE-DATOS-DOMI, status 1, num-env 1
            if (!activo) {
                reg.marcaPendiente();                        // 021643-ALTA-DOMI-PEN: status 0, num-env 0
            }
            Optional<B10Domi> guardado = b10.guardaSiNoExiste(reg);   // STORE ... DMSTATUS(DUPLICATES)
            if (activo && guardado.isPresent()) {
                s702.envia(MensajeDomiciliacion.de(guardado.get()));   // 021236-ARMAREST-ENV-DIALOGO
            }
        }
    }
}

interface B10DomiRepository extends JpaRepository<B10Domi, B10DomiId> {
    /** Cada alta es su propia transacción, como BEGIN/END-TRANSACTION AUDIT S151B99REINICTL. */
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    default Optional<B10Domi> guardaSiNoExiste(B10Domi r) {
        return existsById(r.getId()) ? Optional.empty() : Optional.of(save(r));
    }
}

@Service
@RequiredArgsConstructor
class CancelacionDomiciliacion {

    private final B10DomiRepository b10;
    private final ControlDomiciliacionRepository control;
    private final S702Gateway s702;

    /** 021621/021623: FUNCION 21 cancela todo el proceso; 22 solo lo posterior a AUT-AELIM-S151. */
    void porProceso(MovimientoS500 m) {
        long desde = (m.funcion() == 21) ? 0 : m.autAelimS151();
        boolean activo = control.servicioActivo();
        for (B10Domi r : b10.paraCancelar(m.fecCargo(), m.tipoProc(), desde)) {   // LOCK B10SXPROC
            r.setTipoMov(2);
            if (activo) {
                if (r.getStatus() == 1 || r.getStatus() == 2) {
                    r.setStatus(3);                                  // cancelado y enviado
                    b10.save(r);
                    s702.envia(MensajeDomiciliacion.de(r));
                }
            } else {
                switch (r.getStatus()) {                             // 021624-ALMACENA-PENDIENTE
                    case 0 -> { r.setStatus(6); b10.save(r); }       // nunca enviado: se anula
                    case 1, 2 -> { r.setStatus(5); b10.save(r); }    // enviado: cancelación pendiente
                    default -> { }                                   // otros estados no se tocan
                }
            }
        }
    }
}

@Component
@RequiredArgsConstructor
class ServicioS702Handler {

    private final ControlDomiciliacionRepository control;
    private final FechaContableProvider fechaContable;   // WKS-FECPRO-6D desde L001 CONSISDIA
    private final S702Gateway s702;
    private final MonitorDomiciliacion monitor;

    @ServiceActivator(inputChannel = "s702Entrada")
    void recibe(MensajeS702 msg) {
        if (msg.destino() != 15113 || msg.sistemaDestino() != 151 || msg.direccion() != 1) {
            monitor.eco(msg);                                     // 022220-GUARDA-ECO
            return;
        }
        boolean ordenServicio = (msg.dcod() == 1 || msg.dcod() == 2) && msg.dscod() == 3;
        if (!ordenServicio) {
            monitor.eco(msg);
            return;
        }
        if (!msg.sa2().fecha().equals(fechaContable.actual())) {
            monitor.registra("RECEPCION MENSAJE  S702-S151", msg); // se ignora la orden, sin respuesta
            return;
        }
        control.fijaServicio(msg.dcod() == 1);                    // 022210-ACT-DEACT-SERV
        monitor.registra("RECEPCION MENSAJE  S702-S151", msg);
        s702.responde(msg.respuesta());                           // 022220-ENVIA-RES
    }
}

/**
 * 021222-VALIDA-SERV. A las 06 horas, si el servicio está inactivo, el fuente pregunta
 * en consola (ACCEPT WKS-RESP-OPE) y detiene el proceso hasta que el operador responde.
 * En Java la pregunta se vuelve una alerta y la respuesta una operación administrativa.
 */
void activacionMatutina(ControlDomiciliacion ctl) {
    if (LocalTime.now(clock).getHour() == 6 && !ctl.isServicioActivo()) {
        preguntaMatutinaHecha = true;          // MOVE 1 TO WKS-BAN-HR: se pregunta una sola vez
        alertas.publica("SERVICIO DE ENVIO DE INFORMACION AL S702 NO ACTIVO "
                      + "DESEA ACTIVAR EL SERVICIO: S/N");
    }
}

@ManagedOperation(description = "Respuesta del operador a la activación matutina")
public void respuestaOperador(String resp) {
    if ("S".equals(resp)) {
        control.fijaServicio(true);            // MOVE 1 TO W77-STATUS-SERV
    }
}
